import React, { useEffect, useState } from 'react';
import '../styles/NeonText.css';

const GREETING_COLORS = [
  { yellow: '#FFD700', white: '#fff' },
  { yellow: '#00ff88', white: '#409cff' },
  { yellow: '#ff4ecd', white: '#fff200' },
  { yellow: '#ff9800', white: '#00eaff' },
  { yellow: '#a78bf3', white: '#ffb347' },
  { yellow: '#ff5555', white: '#00ffea' },
];

const NeonText = () => {
  const [colorIndex, setColorIndex] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setColorIndex((prev) => (prev + 1) % GREETING_COLORS.length);
    }, 2000);
    return () => clearInterval(interval);
  }, []);

  const greetingStyleYellow = {
    color: GREETING_COLORS[colorIndex].yellow,
    transition: 'color 0.5s',
    textShadow: `0 0 10px ${GREETING_COLORS[colorIndex].yellow}99`
  };
  const greetingStyleWhite = {
    color: GREETING_COLORS[colorIndex].white,
    transition: 'color 0.5s',
    textShadow: `0 0 10px ${GREETING_COLORS[colorIndex].white}99`
  };

  return (
    <div className="neon-text-container">
      <div className="hero-heading-block align-block">
        <div className="hero-line hero-line1">
          <div className="scrolling-greeting">
            <div className="scrolling-greeting-content">
              <span className="hero-yellow" style={greetingStyleYellow}>Hi there❗ I'm </span>
              <span className="hero-white" style={greetingStyleWhite}> Kushal 🌚  </span>
            </div>
            <div className="scrolling-greeting-content" aria-hidden="true">
              <span className="hero-yellow" style={greetingStyleYellow}>Hi there❗ I'm </span>
              <span className="hero-white" style={greetingStyleWhite}> Kushal 🌚  </span>
            </div>
            <div className="scrolling-greeting-content" aria-hidden="true">
              <span className="hero-yellow" style={greetingStyleYellow}>Hi there❗ I'm </span>
              <span className="hero-white" style={greetingStyleWhite}> Kushal 🌚  </span>
            </div>
            <div className="scrolling-greeting-content" aria-hidden="true">
              <span className="hero-yellow" style={greetingStyleYellow}>Hi there❗ I'm </span>
              <span className="hero-white" style={greetingStyleWhite}> Kushal 🌚  </span>
            </div>
            <div className="scrolling-greeting-content" aria-hidden="true">
              <span className="hero-yellow" style={greetingStyleYellow}>Hi there❗ I'm </span>
              <span className="hero-white" style={greetingStyleWhite}> Kushal 🌚  </span>
            </div>
          </div>
        </div>
        <div className="hero-line hero-line2">
          <div className="scrolling-text">
            <div className="scrolling-text-content">
              <span className="hero-yellow">Building Smart Solutions</span>
              <span className="hero-white">with Code & No-Code</span>
            </div>
            <div className="scrolling-text-content" aria-hidden="true">
              <span className="hero-yellow">Building Smart Solutions</span>
              <span className="hero-white">with Code & No-Code</span>
            </div>
            <div className="scrolling-text-content" aria-hidden="true">
              <span className="hero-yellow">Building Smart Solutions</span>
              <span className="hero-white">with Code & No-Code</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default NeonText;
